def age_group_counts(ages):
    result = {}
    for age in ages:
        if age >= 100:
            label = '100+'
        else:
            decade = (age // 10) * 10
            label = f"{decade}-{decade + 9}"
        result[label] = result.get(label, 0) + 1
    return result

def count_by_sign(nums):
    result = {'positive': 0, 'negative': 0, 'zero': 0}
    for n in nums:
        if n > 0:
            result['positive'] += 1
        elif n < 0:
            result['negative'] += 1
        else:
            result['zero'] += 1
    return result

def count_value_types(d):
    result = {}
    for v in d.values():
        t = type(v).__name__
        result[t] = result.get(t, 0) + 1
    return result

def group_by_length_parity(strings):
    even = []
    odd = []
    for s in strings:
        if len(s) % 2 == 0:
            even.append(s)
        else:
            odd.append(s)
    return {'even_length': sorted(even), 'odd_length': sorted(odd)}

def count_repeated_chars(s):
    counts = {}
    for c in s:
        counts[c] = counts.get(c, 0) + 1
    return {c: n for c, n in counts.items() if n > 1}

def duplicated_items(items):
    counts = {}
    for x in items:
        counts[x] = counts.get(x, 0) + 1
    return sorted([x for x, c in counts.items() if c > 1])

def count_transitions(sequence):
    result = {}
    for i in range(len(sequence) - 1):
        key = f"{sequence[i]}->{sequence[i + 1]}"
        result[key] = result.get(key, 0) + 1
    return result

def value_groups_min_size(d):
    groups = {}
    for k, v in d.items():
        groups.setdefault(v, []).append(k)
    return {v: sorted(ks) for v, ks in groups.items() if len(ks) >= 2}

def count_words_longer_than(text, threshold):
    words = text.split()
    return sum(1 for w in words if len(w) > threshold)

def mode_progression(items):
    running = {}
    result = []
    for x in items:
        running[x] = running.get(x, 0) + 1
        best = None
        best_count = -1
        for val in sorted(running.keys()):
            if running[val] > best_count:
                best_count = running[val]
                best = val
        result.append(best)
    return result

def group_by_mod(nums, m):
    groups = {}
    for n in nums:
        r = n % m
        groups.setdefault(r, []).append(n)
    return {r: sorted(ns) for r, ns in groups.items()}

def weighted_frequency(pairs):
    result = {}
    for item, weight in pairs:
        result[item] = result.get(item, 0) + weight
    return result

def count_chars_excluding(s, exclude):
    excl = set(exclude)
    result = {}
    for c in s:
        if c in excl:
            continue
        result[c] = result.get(c, 0) + 1
    return result

def count_conflicting_keys(d1, d2):
    count = 0
    for k in d1:
        if k in d2 and d1[k] != d2[k]:
            count += 1
    return count

def top_word_per_length(text):
    words = text.split()
    groups = {}
    for w in words:
        groups.setdefault(len(w), []).append(w)
    result = {}
    for length, ws in groups.items():
        counts = {}
        for w in ws:
            counts[w] = counts.get(w, 0) + 1
        best = None
        best_count = -1
        for w in sorted(counts.keys()):
            if counts[w] > best_count:
                best_count = counts[w]
                best = w
        result[length] = best
    return result

def shared_key_sum(dicts_list):
    key_dicts_count = {}
    key_sum = {}
    for d in dicts_list:
        for k, v in d.items():
            key_dicts_count[k] = key_dicts_count.get(k, 0) + 1
            key_sum[k] = key_sum.get(k, 0) + v
    return {k: s for k, s in key_sum.items() if key_dicts_count[k] >= 2}

def category_counts_from_dict(d):
    result = {}
    for cat in d.values():
        result[cat] = result.get(cat, 0) + 1
    return result
